def truncation_detection(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']

        if not text.strip():
            scores.append(-2.0)
            continue

        if not re.search(r'</solution>', text):
            if is_correct(extract_solution(text), gt):
                scores.append(2.0)
            else:
                scores.append(-1.0)
        else:
            scores.append(0.0)
            if is_correct(extract_solution(text), gt):
                scores.append(3.0)

        scores[-1] = scores[-1] if scores[-1] != 0 else (1.0 if is_correct(extract_solution(text), gt) else -0.5)
    return scores

def rambling_detector(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for c, gt in zip(completions, answer):
        text = c[0]['content']
        thinking = extract_thinking(text)
        if not thinking:
